<script>
(function(){
  var data = [
    {d:"May 26",v:34413},
    {d:"May 27",v:34389},
    {d:"May 28",v:34502},
    {d:"May 29",v:34651},
    {d:"Jun 1",v:34588},
    {d:"Jun 2",v:34471},
    {d:"Jun 3",v:34290},
    {d:"Jun 4",v:34162},
    {d:"Jun 5",v:34413},
    {d:"Jun 8",v:34479}
  ];
  var W=680,H=280;
  var margin={left:62,right:24,top:18,bottom:46};
  var PW=W-margin.left-margin.right;
  var PH=H-margin.top-margin.bottom;
  var n=data.length;
  var vals=data.map(function(d){return d.v;});
  var minV=Math.min.apply(null,vals)-200;
  var maxV=Math.max.apply(null,vals)+100;
  function xS(i){return margin.left+i*(PW/(n-1));}
  function yS(v){return margin.top+PH*(1-(v-minV)/(maxV-minV));}
  var svg=document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 "+W+" "+H);
  svg.setAttribute("width","100%");
  function el(tag,attrs){
    var e=document.createElementNS("http://www.w3.org/2000/svg",tag);
    for(var k in attrs) e.setAttribute(k,attrs[k]);
    return e;
  }
  function txt(label,attrs){
    var t=el("text",attrs);
    t.textContent=label;
    return t;
  }
  var fontStack="-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif";
