    svg.appendChild(txt(v.toLocaleString(),{x:margin.left-6,y:y+3,"text-anchor":"end","font-size":"8.5","fill":"#aaa","font-family":fontStack}));
  });
  // Area fill
  var pts=data.map(function(d,i){return xS(i)+","+yS(d.v);}).join(" ");
  var areaPath="M "+xS(0)+","+yS(data[0].v)+" ";
  data.forEach(function(d,i){areaPath+="L "+xS(i)+","+yS(d.v)+" ";});
  areaPath+="L "+xS(n-1)+","+(margin.top+PH)+" L "+xS(0)+","+(margin.top+PH)+" Z";
  var areaEl=el("path",{d:areaPath,fill:"#4a5568",opacity:"0.07"});
  svg.appendChild(areaEl);
  // Line
  var linePath="M";
  data.forEach(function(d,i){linePath+=(i>0?" L ":"")+xS(i)+","+yS(d.v);});
  svg.appendChild(el("path",{d:linePath,fill:"none",stroke:"#4a5568","stroke-width":"2"}));
  // Event band: Jun 7-8 strikes
  var band1X=xS(8)-4;
  var band2X=xS(9)+4;
  var bandW=band2X-band1X+8;
  svg.appendChild(el("rect",{x:band1X,y:margin.top,width:bandW,height:PH,fill:"#c0392b",opacity:"0.05"}));
  svg.appendChild(txt("STRIKES",{x:band1X+bandW/2,y:margin.top+10,"text-anchor":"middle","font-size":"7","font-weight":"700","fill":"#8a3030","font-family":fontStack}));
  // Reference line at pre-strike close Jun 5
  var refY=yS(34413);
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:refY,y2:refY,stroke:"#7a3030","stroke-dasharray":"3,3","stroke-width":"1"}));
  svg.appendChild(txt("Jun 5 CLOSE 34,413",{x:650,y:refY-4,"text-anchor":"end","font-size":"7.5","fill":"#7a3030","font-family":fontStack}));
  // Data points
  data.forEach(function(d,i){
    svg.appendChild(el("circle",{cx:xS(i),cy:yS(d.v),r:"2.5",fill:"#4a5568"}));
  });
  // Gold pill on last point
  var lastX=xS(n-1);
  var lastY=yS(data[n-1].v);
  var pillW=64,pillH=16;
  var pillX=lastX-pillW-6;
  var pillY=lastY-pillH/2;
  svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:"4",fill:"#4a5568"}));
  svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,fill:"#e8a825",rx:"2"}));
  svg.appendChild(txt("34,479",{x:pillX+pillW/2,y:pillY+pillH/2+3.5,"text-anchor":"middle","font-size":"9","font-weight":"700","fill":"#111","font-family":fontStack}));
  // X-axis labels
  var labelIdx=[0,2,4,6,8,9];
  data.forEach(function(d,i){
    if(labelIdx.indexOf(i)>=0){
      svg.appendChild(txt(d.d,{x:xS(i),y:margin.top+PH+14,"text-anchor":"middle","font-size":"8","fill":"#999","font-family":fontStack}));
    }
  });
  // Axis line
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:margin.top+PH,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));
  var container=document.currentScript?document.currentScript.parentNode:null;
  if(container) container.appendChild(svg);
})();
